// One Actor run for the whole list (up to 10,000 keywords). Empty and duplicate cells are skipped.
const cfg = $('Configure').first().json;
const keywords = [...new Set($input.all().map(i => String(i.json.keyword ?? '').trim()).filter(Boolean))];
return [{ json: { keywords, countries: cfg.countries, historyMonths: cfg.historyMonths } }];

// Flat rows for the History tab. Notes about the input (invalid keywords, limits) are skipped.
const checked = new Date().toISOString().slice(0, 10);
return $input.all().filter(i => i.json.keyword && i.json.country).map(i => ({ json: {
  checked, keyword: i.json.keyword, country: i.json.country, volume: i.json.searchVolume ?? '',
  cpcUsd: i.json.cpcUsd ?? '', competition: i.json.competition ?? '', trend3mPct: i.json.trend3mPct ?? '',
  trendYoYPct: i.json.trendYoYPct ?? '', trend: i.json.trendDirection ?? '', status: i.json.status } }));

// Rising and falling keywords (3-month trend) and the biggest ones, as one plain-text e-mail.
const cfg = $('Configure').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.volume !== '');
const line = r => `- ${r.keyword} (${r.country}): ${Number(r.volume).toLocaleString('en-US')}/mo, CPC $${r.cpcUsd || 0}, 3 months ${r.trend3mPct > 0 ? '+' : ''}${r.trend3mPct}%`;
const by = (f, n) => rows.filter(f).sort((a, b) => Math.abs(b.trend3mPct) - Math.abs(a.trend3mPct)).slice(0, n).map(line);
const rising = by(r => r.trend === 'rising', 10), falling = by(r => r.trend === 'falling', 10);
const top = [...rows].sort((a, b) => b.volume - a.volume).slice(0, 10).map(line);
const text = [`Keyword check ${rows[0]?.checked ?? ''}: ${rows.length} keyword/country rows with data.`, '',
  'Rising:', ...(rising.length ? rising : ['- none']), '', 'Falling:', ...(falling.length ? falling : ['- none']), '',
  'Biggest:', ...top, '', 'Full history is in the History tab of your sheet.'].join('\n');
return [{ json: { sendTo: cfg.sendTo, subject: `Keyword volumes: ${rising.length} rising, ${falling.length} falling`, text } }];
